.darma-loader-darma-b16-revolving-door { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 116px); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b16-revolving-door .darma-loader-darma-b16-revolving-door__drum { position: absolute; inset: 0; border-radius: 50%; box-shadow: inset 0 0 0 5px color-mix(in srgb, var(--accent) 45%, transparent); mask: conic-gradient(from 20deg, #000 0 140deg, transparent 140deg 180deg, #000 180deg 320deg, transparent 320deg); -webkit-mask: conic-gradient(from 20deg, #000 0 140deg, transparent 140deg 180deg, #000 180deg 320deg, transparent 320deg); }
.darma-loader-darma-b16-revolving-door .darma-loader-darma-b16-revolving-door__vanes { position: absolute; inset: 8%; animation: darma-loader-darma-b16-revolving-door-door-turn calc(var(--loader-speed, 1s) * 3) linear infinite; }
.darma-loader-darma-b16-revolving-door .darma-loader-darma-b16-revolving-door__vanes span { position: absolute; left: 50%; top: 50%; width: 100%; height: 7%; margin: -3.5% 0 0 -50%; border-radius: 4px; background: linear-gradient(90deg, color-mix(in srgb, var(--accent-2) 60%, transparent), var(--accent-2), color-mix(in srgb, var(--accent-2) 60%, transparent)); }
.darma-loader-darma-b16-revolving-door .darma-loader-darma-b16-revolving-door__vanes span:nth-of-type(2) { transform: rotate(90deg); }
.darma-loader-darma-b16-revolving-door i { position: absolute; width: 13%; height: 13%; border-radius: 50%; background: var(--accent); animation: darma-loader-darma-b16-revolving-door-door-walk calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b16-revolving-door i:nth-of-type(1) { left: 2%; top: 44%; --dir: 1; }
.darma-loader-darma-b16-revolving-door i:nth-of-type(2) { left: 76%; top: 44%; --dir: -1; animation-delay: calc(var(--loader-speed, 1s) * -1.5); }
@keyframes darma-loader-darma-b16-revolving-door-door-turn { to { transform: rotate(1turn); } }
@keyframes darma-loader-darma-b16-revolving-door-door-walk { 0% { transform: translateX(0); opacity: 0; } 14% { opacity: 1; } 84% { opacity: 1; } 100% { transform: translateX(calc(var(--dir, 1) * 570%)); opacity: 0; } }

